1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Base premiums: single items -------------------------------------
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it.todo("sword → base premium 100 G");
15	  it.todo("amulet → base premium 60 G");
16	  it.todo("staff → base premium 80 G");
17	  it.todo("potion → base premium 40 G");
18	  it.todo("single rune → base premium 25 G");
19	  it.todo("single moonstone → base premium 25 G");
20	
21	  // --- Component blocks --------------------------------------------------
22	  it.todo("2 runes → 50 G base premium");
23	  it.todo("3 runes → 60 G base premium (block applies)");
24	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
25	  it.todo("7 runes → 175 G base premium");
26	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
27	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
28	
29	  // --- Item-specific modifiers ------------------------------------------
30	  it.todo("cursed sword adds 50 % of its base premium as risk surcharge");
31	  it.todo("sword with enchantment 5 → high-enchantment surcharge applies (30 %)");
32	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
33	  it.todo("cursed sword with enchantment 5 → both surcharges apply");
34	
35	  // --- Policy-wide modifiers ---------------------------------------------
36	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
37	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
38	  it.todo("first quote carries a 10 % initial assessment surcharge");
39	  it.todo("second quote in a scenario receives a 15 % follow-up contract discount");
40	  it.todo("first insurance surcharge still applies on a follow-up contract");
41	
42	  // --- Modifier scope on multi-item policies ------------------------------
43	  it.todo(
44	    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G → 210 G before further modifiers and fee",
45	  );
46	
47	  // --- Rounding ------------------------------------------------------------
48	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
49	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
50	
51	  // --- Integration examples -------------------------------------------------
52	  it.todo("newcomer with a cursed sword (steel, enchantment 3) → premium 165 G");
53	  it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G");
54	
55	  // --- Claim: standard reimbursement ----------------------------------------
56	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
57	  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");
58	
59	  // --- Claim: special clauses ------------------------------------------------
60	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G");
61	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G");
62	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
63	  it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G");
64	
65	  // --- Claim: deductible per damage event -------------------------------------
66	  it.todo("dragon attack damaging sword (500 G) and amulet (300 G) → payout 600 G");
67	
68	  // --- Claim: cap ---------------------------------------------------------------
69	  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
70	  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
71	  it.todo("cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
72	  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G");
73	  it.todo("sword, two successive claims of 1500 G → first payout 1400 G, remaining cap 600 G");
74	  it.todo("sword, second claim of 1500 G → payout 600 G, remaining cap 0 G");
75	
76	  // --- Claim: multiple items of the same type -------------------------------------
77	  it.todo("two swords insured, two sword damages → each damage gets its own deductible");
78	  it.todo("more damage entries of a type than insured → claim rejected (error)");
79	
80	  // --- Errors ------------------------------------------------------------------------
81	  it.todo("quote with an unknown item type (broomstick) → error");
82	  it.todo("claim referencing an item not part of the policy (amulet, only sword insured) → error");
83	  it.todo("claim referencing a damage entry with an unknown item type → error");
84	  it.todo("claim with a damage entry of amount -200 → error");
85	
86	  // --- CLI ---------------------------------------------------------------------------
87	  it.todo("CLI reads a scenario from stdin and writes results JSON to stdout");
88	  it.todo("CLI exits with a non-zero status and writes to stderr on an invalid scenario");
